from collections import deque

def main():
    buf = deque()
    capacity = 6
    ticket = 0
    operations = [
        "Issue", "Issue", "Issue", "Issue", "Issue", "Issue",
        "Issue", "Report", "Issue", "Report"
    ]
    for op in operations:
        if op == "Issue":
            ticket += 1
            if len(buf) == capacity:
                buf.popleft()
            buf.append(ticket)
            print(f"Issued: {ticket}")
        elif op == "Report":
            print("Buffer: " + " ".join(str(x) for x in buf))
    print(f"Count: {len(buf)}")

if __name__ == "__main__":
    main()

