import sys

def main():
    valid = []
    invalid = 0
    try:
        with open('readings.txt', 'r') as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        lines = []

    for line in lines:
        parts = line.split()
        if len(parts) != 5:
            invalid += 1
            continue
        zone, temp_s, hum_s, light_s, soil = parts
        try:
            temp = float(temp_s)
            hum = int(hum_s)
            light = int(light_s)
        except ValueError:
            invalid += 1
            continue
        if not (0 <= hum <= 100):
            invalid += 1
            continue
        if soil not in ('wet', 'ok', 'dry'):
            invalid += 1
            continue
        valid.append((zone, temp, hum, light, soil))

    n = len(valid)
    print(f"Readings processed: {n}")
    print(f"Invalid readings: {invalid}")

    if n > 0:
        avg_temp = sum(v[1] for v in valid) / n
        print(f"Average temperature: {round(avg_temp, 1)}")
    else:
        print("Average temperature: 0.0")

    if n > 0:
        hottest = valid[0]
        for v in valid[1:]:
            if v[1] > hottest[1]:
                hottest = v
        print(f"Hottest zone: {hottest[0]}")
    else:
        print("Hottest zone: ")

    dry_count = sum(1 for v in valid if v[4] == 'dry')
    wet_count = sum(1 for v in valid if v[4] == 'wet')
    print(f"Dry soil count: {dry_count}")
    print(f"Wet soil count: {wet_count}")

    dry_hums = [v[2] for v in valid if v[4] == 'dry']
    if dry_hums:
        avg_dry_hum = sum(dry_hums) / len(dry_hums)
