from functools import lru_cache

blocked = {(1, 1), (2, 0), (0, 2)}
target = (3, 3)

@lru_cache(maxsize=None)
def count(x, y, diags, via22):
    if (x, y) in blocked:
        return 0
    if (x, y) == target:
        return 1
    if x > 3 or y > 3:
        return 0
    total = 0
    # Right
    total += count(x + 1, y, diags, via22 or (x + 1, y) == (2, 2))
    # Down
    total += count(x, y + 1, diags, via22 or (x, y + 1) == (2, 2))
    # Diagonal
    if diags < 2:
        total += count(x + 1, y + 1, diags + 1, via22 or (x + 1, y + 1) == (2, 2))
    return total

total_paths = count(0, 0, 0, False)

# Two diagonal paths: count with exactly 2 diags allowed (already limited to 2)
# but need exactly 2, so subtract those with fewer. Recompute with exact tracking.

@lru_cache(maxsize=None)
def count_exact(x, y, diags, via22):
    if (x, y) in blocked:
        return 0
    if (x, y) == target:
        return 1 if diags == 2 else 0
    if x > 3 or y > 3:
        return 0
    total = 0
    total += count_exact(x + 1, y, diags, via22 or (x + 1, y) == (2, 2))
    total += count_exact(x, y + 1, diags, via22 or (x, y + 1) == (2, 2))
    if diags < 2:
        total += count_exact(x + 1, y + 1, diags + 1, via22 or (x + 1, y + 1) == (2, 2))
    return total

two_diag = count_exact(0, 0, 0, False)

# Via (2,2): count paths that pass through (2,2)
# paths from (0,0) to (2,2) avoiding blocked, times paths from (2,2) to (3,3) avoiding blocked
# but need to ensure (2,2) not blocked (it isn't)

@lru_cache(maxsize=None)
def count_to(x, y, tx, ty):
    if (x, y) in blocked:
        return 0
    if (x, y) == (tx, ty):
        return 1
    if x > tx or y > ty:
        return 0
    return count_to(x + 1, y, tx, ty) + count_to(x, y + 1, tx, ty) + count_to(x + 1, y + 1, tx, ty)

via22 = count_to(0, 0, 2, 2) * count_to(2, 2, 3, 3)

